const getTopGrowingFolders = `-- name: GetTopGrowingFolders :many
WITH folder_changes AS (
    SELECT
        f.id,
        f.volume_id,
        f.path,
        f.size_bytes_recursive as current_size,
        f.file_count_recursive as file_count,
        f.modified_at as updated_at,
        COALESCE(LAG(f.size_bytes_recursive) OVER (PARTITION BY f.path ORDER BY f.modified_at), f.size_bytes_recursive) as previous_size
    FROM folders f
    WHERE f.volume_id = $1
      AND f.modified_at >= $2
)
SELECT
    id,
    volume_id,
    path,
    current_size,
    file_count,
    updated_at,
    previous_size,
    (current_size - previous_size) as size_change,
    CASE
        WHEN previous_size > 0 THEN ((current_size - previous_size)::float / previous_size::float * 100)
        ELSE 0
    END as growth_percent
FROM folder_changes
WHERE (current_size - previous_size) > 0
ORDER BY (current_size - previous_size) DESC
LIMIT $3
`

type GetTopGrowingFoldersParams struct {
	VolumeID   string             `json:"volume_id"`
	ModifiedAt pgtype.Timestamptz `json:"modified_at"`
	Limit      int32              `json:"limit"`
}

type GetTopGrowingFoldersRow struct {
	ID            int64       `json:"id"`
	VolumeID      string      `json:"volume_id"`
	Path          string      `json:"path"`
	CurrentSize   pgtype.Int8 `json:"current_size"`
	FileCount     pgtype.Int4 `json:"file_count"`
	UpdatedAt     time.Time   `json:"updated_at"`
	PreviousSize  pgtype.Int8 `json:"previous_size"`
	SizeChange    int32       `json:"size_change"`
	GrowthPercent int32       `json:"growth_percent"`
}

func (q *Queries) GetTopGrowingFolders(ctx context.Context, arg GetTopGrowingFoldersParams) ([]GetTopGrowingFoldersRow, error) {
	rows, err := q.db.Query(ctx, getTopGrowingFolders, arg.VolumeID, arg.ModifiedAt, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []GetTopGrowingFoldersRow{}
	for rows.Next() {
		var i GetTopGrowingFoldersRow
		if err := rows.Scan(
			&i.ID,
			&i.VolumeID,
			&i.Path,
			&i.CurrentSize,
			&i.FileCount,
			&i.UpdatedAt,
			&i.PreviousSize,
			&i.SizeChange,
			&i.GrowthPercent,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const getTrendAnalysis = `-- name: GetTrendAnalysis :one

WITH stats_window AS (
    SELECT
        date,
        total_size_bytes,
        total_files,
        size_change_bytes,
        growth_percent
    FROM daily_stats
    WHERE volume_id = $1
      AND date >= CURRENT_DATE - $2::int
    ORDER BY date DESC
)
SELECT
    $1 as volume_id,
    COUNT(*) as data_points,
    MAX(date) as latest_date,
    SUM(total_files) as total_files,
    SUM(total_size_bytes) as total_bytes,
    AVG(size_change_bytes)::bigint as avg_daily_change,
    AVG(growth_percent)::numeric as avg_growth_rate,
    MAX(size_change_bytes) as max_daily_change,
    MIN(size_change_bytes) as min_daily_change,
    STDDEV(size_change_bytes)::bigint as change_stddev
FROM stats_window
`

type GetTrendAnalysisParams struct {
	VolumeID string `json:"volume_id"`
	Column2  int32  `json:"column_2"`
}

type GetTrendAnalysisRow struct {
	VolumeID       interface{}    `json:"volume_id"`
	DataPoints     int64          `json:"data_points"`
	LatestDate     interface{}    `json:"latest_date"`
	TotalFiles     int64          `json:"total_files"`
	TotalBytes     int64          `json:"total_bytes"`
	AvgDailyChange int64          `json:"avg_daily_change"`
	AvgGrowthRate  pgtype.Numeric `json:"avg_growth_rate"`
	MaxDailyChange interface{}    `json:"max_daily_change"`
	MinDailyChange interface{}    `json:"min_daily_change"`
	ChangeStddev   int64          `json:"change_stddev"`
}

// =============================================================================
// TREND ANALYSIS
// =============================================================================
func (q *Queries) GetTrendAnalysis(ctx context.Context, arg GetTrendAnalysisParams) (GetTrendAnalysisRow, error) {
	row := q.db.QueryRow(ctx, getTrendAnalysis, arg.VolumeID, arg.Column2)
	var i GetTrendAnalysisRow
	err := row.Scan(
		&i.VolumeID,
		&i.DataPoints,
		&i.LatestDate,
		&i.TotalFiles,
		&i.TotalBytes,
		&i.AvgDailyChange,
		&i.AvgGrowthRate,
		&i.MaxDailyChange,
		&i.MinDailyChange,
		&i.ChangeStddev,
	)
	return i, err
}

const getVolumeComparison = `-- name: GetVolumeComparison :many
SELECT
    v.volume_id,
    v.display_name as name,
    COALESCE(v.total_size_bytes, 0) as total_bytes,
    COALESCE((SELECT COUNT(*) FROM files f WHERE f.volume_id = v.volume_id AND f.is_dir = false), 0) as total_files,
    v.last_scan_at as last_scanned,
    COALESCE(ds.growth_percent, 0) as growth_rate,
    COALESCE(ds.size_change_bytes, 0) as recent_change
FROM volumes v
LEFT JOIN LATERAL (
    SELECT growth_percent, size_change_bytes
    FROM daily_stats
    WHERE volume_id = v.volume_id
    ORDER BY date DESC
    LIMIT 1
) ds ON true
WHERE v.is_active = true
ORDER BY total_bytes DESC
LIMIT $1
`

