const updateStatsJob = `-- name: UpdateStatsJob :exec
UPDATE stats_jobs
SET
    status = $2,
    progress = $3,
    error_message = $4,
    updated_at = CURRENT_TIMESTAMP,
    completed_at = CASE WHEN $2 IN ('completed', 'failed', 'cancelled') THEN CURRENT_TIMESTAMP ELSE completed_at END,
    duration_ms = CASE WHEN $2 IN ('completed', 'failed', 'cancelled') THEN EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP - started_at)) * 1000 ELSE duration_ms END
WHERE job_id = $1
`

type UpdateStatsJobParams struct {
	JobID        string      `json:"job_id"`
	Status       string      `json:"status"`
	Progress     pgtype.Int4 `json:"progress"`
	ErrorMessage pgtype.Text `json:"error_message"`
}

func (q *Queries) UpdateStatsJob(ctx context.Context, arg UpdateStatsJobParams) error {
	_, err := q.db.Exec(ctx, updateStatsJob,
		arg.JobID,
		arg.Status,
		arg.Progress,
		arg.ErrorMessage,
	)
	return err
}

